  s <- sum(nums)
  m <- round(mean(nums), 2)
  return(paste(s, m))
}

add_two <- function(input) {
  lines <- strsplit(input, "\n")[[1]]
  a <- as.numeric(lines[1])
  b <- as.numeric(lines[2])
  if (is.na(a) || is.na(b)) {
    return("invalid")
  }
  return(as.character(a + b))
}

