passing <- function(input) {
  lines <- strsplit(input, "\n")[[1]]
  passed <- c()
  for (line in lines) {
    parts <- strsplit(line, ",")[[1]]
    name <- parts[1]
    score <- as.numeric(parts[2])
    if (!is.na(score) && score >= 60) {
      passed <- c(passed, name)
    }
  }
  return(paste(passed, collapse = " "))
}

